$old = "C:\Users\Administrator\.claude\projects\E--project--------------"
$sessions = @(
  "46438792-88c4-419f-b241-abef6e2fe963",
  "a69b9bf7-23ce-4e86-ba6f-6e39a337283d",
  "76542781-294e-441d-bf18-b26a034a3624",
  "d80bda74-de4a-40c0-8adb-80b5b339b9fa"
)
foreach ($sid in $sessions) {
  $f = Join-Path $old "$sid.jsonl"
  if (-not (Test-Path $f)) { Write-Host "MISSING $sid"; continue }
  $info = Get-Item $f
  Write-Host "`n======== $sid ========"
  Write-Host ("Size: {0:N0} KB | Modified: {1}" -f ($info.Length/1KB), $info.LastWriteTime)
  # first few user messages
  $count = 0
  Get-Content $f -Encoding UTF8 | ForEach-Object {
    if ($count -ge 8) { return }
    try {
      $o = $_ | ConvertFrom-Json -ErrorAction Stop
      $type = $o.type
      if ($type -eq 'user' -or $o.role -eq 'user' -or ($o.message -and $o.message.role -eq 'user')) {
        $text = $null
        if ($o.message.content) {
          if ($o.message.content -is [string]) { $text = $o.message.content }
          elseif ($o.message.content[0].text) { $text = $o.message.content[0].text }
          elseif ($o.message.content.text) { $text = $o.message.content.text }
        } elseif ($o.content) {
          if ($o.content -is [string]) { $text = $o.content }
          elseif ($o.content[0].text) { $text = $o.content[0].text }
        } elseif ($o.text) { $text = $o.text }
        if ($text -and $text.Length -gt 0 -and $text -notmatch 'tool_result|tool_use') {
          $snip = if ($text.Length -gt 200) { $text.Substring(0,200) + '...' } else { $text }
          $snip = $snip -replace "`r?`n", ' '
          Write-Host "USER: $snip"
          $count++
        }
      }
    } catch {}
  }
}

