$old = "C:\Users\Administrator\.claude\projects\E--project--------------"
$new = "C:\Users\Administrator\.claude\projects\E--project---------"

# Copy session transcripts + any side dirs
Get-ChildItem $old -Force | Where-Object { $_.Name -ne 'memory' } | ForEach-Object {
  $dest = Join-Path $new $_.Name
  if (Test-Path $dest) {
    Write-Host "SKIP (exists): $($_.Name)"
  } else {
    Copy-Item $_.FullName $dest -Recurse -Force
    Write-Host "COPIED: $($_.Name)"
  }
}

# Also merge old memory if any useful files
if (Test-Path (Join-Path $old "memory")) {
  Get-ChildItem (Join-Path $old "memory") -Force | ForEach-Object {
    $dest = Join-Path $new "memory\$($_.Name)"
    if (-not (Test-Path $dest)) {
      Copy-Item $_.FullName $dest -Recurse -Force
      Write-Host "MEMORY COPIED: $($_.Name)"
    }
  }
}

Write-Host "`n==== New project dir now ===="
Get-ChildItem $new | Select-Object Name, Mode, Length, LastWriteTime | Format-Table -AutoSize

# Update history.jsonl project path for old sessions so picker shows them under new cwd
$hist = "C:\Users\Administrator\.claude\history.jsonl"
$bak = "C:\Users\Administrator\.claude\history.jsonl.bak-rename-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
Copy-Item $hist $bak
Write-Host "History backup: $bak"

$oldPath = 'E:\\project\\亚马逊平台驾驶舱-店铺数据'
$newPath = 'E:\\project\\亚马逊平台驾驶舱'
$content = [System.IO.File]::ReadAllText($hist, [System.Text.Encoding]::UTF8)
$updated = $content.Replace($oldPath, $newPath)
if ($content -eq $updated) {
  # try with single backslash variant as stored
  $oldPath2 = 'E:\project\亚马逊平台驾驶舱-店铺数据'
  $newPath2 = 'E:\project\亚马逊平台驾驶舱'
  $updated = $content.Replace($oldPath2, $newPath2)
}
[System.IO.File]::WriteAllText($hist, $updated, (New-Object System.Text.UTF8Encoding $false))
$check = (Select-String -Path $hist -Pattern '亚马逊平台驾驶舱-店铺数据' -SimpleMatch | Measure-Object).Count
$checkNew = (Select-String -Path $hist -Pattern '亚马逊平台驾驶舱"' -SimpleMatch | Measure-Object).Count
Write-Host "Remaining old-path hits: $check"
Write-Host "Done. Sessions available under current project."
